  create(input:any){const id=newId(),stamp=now(),url=normalizeUrl(String(input.url));const title=String(input.title||new URL(url).hostname).trim();if(!title||[...title].length>500)throw new Error('Title must be between 1 and 500 characters');const description=input.description?String(input.description).trim().slice(0,4000):null;const note=String(input.noteMarkdown??'');const attempt=newId(),job=newId();return this.db.transaction(()=>{this.db.prepare(`INSERT INTO bookmarks(id,url,normalized_url,title,description,note_markdown,note_text,read_status,copy_status,favicon_url,preview_image_url,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(id,url,url,title,description,note,markdownText(note),input.readStatus==='read'?'read':'unread','pending',input.faviconUrl??null,input.previewImageUrl??null,stamp,stamp);this.syncTags(id,input.tags??[]);this.syncFts(id);this.db.prepare('INSERT INTO capture_attempts(id,bookmark_id,state,created_at,updated_at) VALUES(?,?,?,?,?)').run(attempt,id,'queued',stamp,stamp);this.db.prepare('INSERT INTO jobs(id,kind,payload,state,run_after,created_at) VALUES(?,?,?,\'queued\',?,?)').run(job,'capture',JSON.stringify({bookmarkId:id,attemptId:attempt}),stamp,stamp);return this.get(id)!})()}
