  list(options:ListOptions={}):Page<BookmarkDTO>{const scope=options.scope??'active';let rows=this.db.prepare('SELECT * FROM bookmarks WHERE deleted_at IS NULL').all() as any[];rows=rows.filter(r=>scope==='all'||(scope==='archived'?!!r.archived_at:scope==='unread'?!r.archived_at&&r.read_status==='unread':!r.archived_at));const ast=parseSearch(options.q??'');const selectedTags=(options.tags??[]).map(canonicalTag);rows=rows.filter(r=>{const tags=this.tagsFor(r.id).map(t=>t.name);return selectedTags.every(t=>tags.some(x=>canonicalTag(x)===t))&&matchesSearch(ast,{text:[r.title,r.url,r.description,r.note_text,...tags].filter(Boolean).join(' '),tags})});const field=options.sort??'created_at',dir=options.direction??'desc';rows.sort((a,b)=>{const av=field==='title'?a.title.toLocaleLowerCase():a[field],bv=field==='title'?b.title.toLocaleLowerCase():b[field];const cmp=String(av).localeCompare(String(bv));return (dir==='asc'?cmp:-cmp)||String(a.id).localeCompare(String(b.id))});const total=rows.length,page=Math.max(1,options.page??1),pageSize=Math.min(100,Math.max(1,options.pageSize??30));return {items:rows.slice((page-1)*pageSize,page*pageSize).map(r=>this.dto(r)),total,page,pageSize}}
  tags(){return this.db.prepare('SELECT t.id,t.display_name name,count(bt.bookmark_id) count FROM tags t LEFT JOIN bookmark_tags bt ON bt.tag_id=t.id GROUP BY t.id ORDER BY t.display_name COLLATE NOCASE').all()}
  update(id:string,input:any){return this.db.transaction(()=>{const current=this.db.prepare('SELECT * FROM bookmarks WHERE id=? AND deleted_at IS NULL').get(id) as any;if(!current)throw new Error('Bookmark not found');if(input.version!==undefined&&input.version!==current.version)throw new Error('This bookmark changed; refresh and try again');let url=current.url,revision=current.url_revision;if(input.url!==undefined){url=normalizeUrl(String(input.url));if(url!==current.normalized_url)revision++}const title=input.title!==undefined?String(input.title).trim():current.title;if(!title||[...title].length>500)throw new Error('Title must be between 1 and 500 characters');const description=input.description!==undefined?(String(input.description).trim()||null):current.description;const note=input.noteMarkdown!==undefined?String(input.noteMarkdown):current.note_markdown;this.db.prepare(`UPDATE bookmarks SET url=?,normalized_url=?,title=?,description=?,note_markdown=?,note_text=?,read_status=?,favicon_url=?,preview_image_url=?,updated_at=?,url_revision=?,version=version+1 WHERE id=?`).run(url,url,title,description, note,markdownText(note??''),input.readStatus??current.read_status,input.faviconUrl===undefined?current.favicon_url:input.faviconUrl,input.previewImageUrl===undefined?current.preview_image_url:input.previewImageUrl,now(),revision,id);if(input.tags)this.syncTags(id,input.tags);this.syncFts(id);return this.get(id)!})()}
