  bulk(ids:string[],action:string,data:any={}){if(!Array.isArray(ids)||ids.length<1||ids.length>500||new Set(ids).size!==ids.length)throw new Error('Choose between 1 and 500 unique bookmarks');const succeeded:string[]=[],failed:Array<{id:string;reason:string}>=[];this.db.transaction(()=>{for(const id of ids){try{const b=this.get(id);if(!b)throw new Error('Not found');if(action==='read'||action==='unread')this.update(id,{readStatus:action,version:b.version});else if(action==='archive'||action==='restore')this.setArchived(id,action==='archive');else if(action==='delete')this.delete(id);else if(action==='addTags'||action==='removeTags'){const names=b.tags.map(t=>t.name),targets=validateTags(data.tags??[]);const next=action==='addTags'?[...names,...targets]:names.filter(n=>!targets.some(t=>canonicalTag(t)===canonicalTag(n)));this.update(id,{tags:next,version:b.version})}else throw new Error('Unsupported action');succeeded.push(id)}catch(e){failed.push({id,reason:(e as Error).message})}}})();// outer transaction
