  updatePreferences(input:any){const p:any=this.preferences();const sort=['title','created_at','updated_at'].includes(input.defaultSort)?input.defaultSort:p.defaultSort;const direction=['asc','desc'].includes(input.sortDirection)?input.sortDirection:p.sortDirection;const size=['small','medium','large'].includes(input.textSize)?input.textSize:p.textSize;this.db.prepare('UPDATE preferences SET default_sort=?,sort_direction=?,text_size=? WHERE id=1').run(sort,direction,size);return this.preferences()}
