function sanitizeHtml(html:string,effectiveUrl:string){const dom=new JSDOM(html,{url:effectiveUrl}),doc=dom.window.document;doc.querySelectorAll('script,iframe,frame,object,embed,form,input,button,textarea,select,meta[http-equiv="refresh"],link[rel="preload"],link[rel="prefetch"]').forEach(n=>n.remove());for(const el of [...doc.querySelectorAll('*')]){for(const attr of [...el.attributes]){if(attr.name.toLowerCase().startsWith('on')||['srcset','integrity','nonce'].includes(attr.name.toLowerCase()))el.removeAttribute(attr.name)}if(el.tagName==='A'){const href=el.getAttribute('href');if(href)try{el.setAttribute('href',new URL(href,effectiveUrl).toString());el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer')}catch{el.removeAttribute('href')}}else for(const name of ['src','href','poster'])if(el.hasAttribute(name))el.removeAttribute(name)}const base=doc.createElement('base');base.href='about:blank';doc.head.prepend(base);const style=doc.createElement('style');style.textContent='html{color-scheme:light dark}body{max-width:76ch;margin:2rem auto;padding:0 1.25rem;font:18px/1.65 system-ui,sans-serif}img{max-width:100%;height:auto}a{color:#2365a8}';doc.head.append(style);return '<!doctype html>'+doc.documentElement.outerHTML}
export async function captureBookmark(db:DB,config:AppConfig,bookmarkId:string,attemptId:string){const bookmark=db.prepare('SELECT * FROM bookmarks WHERE id=?').get(bookmarkId) as any;if(!bookmark)return;const store=new BlobStore(config.blobDir,config.tmpDir);await store.init();db.prepare("UPDATE capture_attempts SET state='running',attempts=attempts+1,updated_at=? WHERE id=?").run(now(),attemptId);try{const response=await safeFetch(bookmark.url);if(!response.ok)throw new Error(`HTTP ${response.status}`);const declared=(response.headers.get('content-type')??'').toLowerCase();const bytes=await boundedBytes(response,declared.includes('pdf')?config.pdfMaxBytes:config.captureMaxBytes);const isPdf=declared.includes('application/pdf')||bytes.subarray(0,5).toString()==='%PDF-';if(isPdf&&bytes.subarray(0,5).toString()!=='%PDF-')throw new Error('The server claimed PDF content but the file was not a valid PDF');const content=isPdf?bytes:Buffer.from(sanitizeHtml(bytes.toString('utf8'),response.url));const blob=await store.put(content),copyId=newId(),stamp=now(),media=isPdf?'application/pdf':'text/html; charset=utf-8';db.transaction(()=>{db.prepare('INSERT OR IGNORE INTO blobs VALUES(?,?,?,?,?)').run(blob.digest,blob.size,media,blob.path,stamp);db.prepare('INSERT INTO saved_copies VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(copyId,bookmarkId,bookmark.url,response.url,bookmark.url_revision,isPdf?'pdf':'html',blob.digest,blob.size,media,stamp,0);db.prepare("UPDATE bookmarks SET current_saved_copy_id=?,copy_status='available',copy_error_code=NULL WHERE id=?").run(copyId,bookmarkId);db.prepare("UPDATE capture_attempts SET state='available',updated_at=? WHERE id=?").run(stamp,attemptId)})()}catch(error){const detail=(error as Error).message.slice(0,500);db.transaction(()=>{db.prepare("UPDATE capture_attempts SET state='failed',error_code='capture_failed',error_detail=?,updated_at=? WHERE id=?").run(detail,now(),attemptId);db.prepare("UPDATE bookmarks SET copy_status=CASE WHEN current_saved_copy_id IS NULL THEN 'failed' ELSE copy_status END,copy_error_code=? WHERE id=?").run(detail,bookmarkId)})()}}

