import { captureBookmark } from '../capture/capture.js';
export function startWorker(db:DB,config:AppConfig){let active=0,stopped=false;const tick=async()=>{if(stopped||active>=config.captureConcurrency)return;const job=db.prepare("SELECT * FROM jobs WHERE state='queued' AND run_after<=? ORDER BY created_at LIMIT 1").get(now()) as any;if(!job)return;const changed=db.prepare("UPDATE jobs SET state='running',leased_until=?,attempts=attempts+1 WHERE id=? AND state='queued'").run(new Date(Date.now()+60000).toISOString(),job.id);if(!changed.changes)return;active++;try{const payload=JSON.parse(job.payload);await captureBookmark(db,config,payload.bookmarkId,payload.attemptId);db.prepare("UPDATE jobs SET state='done',leased_until=NULL WHERE id=?").run(job.id)}catch{db.prepare("UPDATE jobs SET state='failed',leased_until=NULL WHERE id=?").run(job.id)}finally{active--}};db.prepare("UPDATE jobs SET state='queued',leased_until=NULL WHERE state='running' AND leased_until<?").run(now());const timer=setInterval(()=>void tick(),600);timer.unref();return {stop(){stopped=true;clearInterval(timer)},status(){return {active,queued:(db.prepare("SELECT count(*) n FROM jobs WHERE state='queued'").get() as any).n}}}}

