function blocked4(ip:string){const p=ip.split('.').map(Number);return p[0]===0||p[0]===10||p[0]===127||p[0]===169&&p[1]===254||p[0]===172&&p[1]!>=16&&p[1]!<=31||p[0]===192&&p[1]===168||p[0]>=224}
function blocked6(ip:string){const value=ip.toLowerCase();return value==='::'||value==='::1'||value.startsWith('fc')||value.startsWith('fd')||value.startsWith('fe8')||value.startsWith('fe9')||value.startsWith('fea')||value.startsWith('feb')||value.startsWith('ff')||value.startsWith('::ffff:127.')||value.startsWith('::ffff:10.')||value.startsWith('::ffff:192.168.')}
export async function assertPublicUrl(value:string){const url=new URL(value);if(!['http:','https:'].includes(url.protocol))throw new Error('Only public HTTP and HTTPS addresses can be captured');if(url.username||url.password)throw new Error('Credential-bearing addresses cannot be captured');if(url.port&&!['80','443'].includes(url.port))throw new Error('Only standard web ports can be captured');if(url.hostname==='localhost'||url.hostname.endsWith('.localhost')||url.hostname.endsWith('.local'))throw new Error('Private addresses cannot be captured');const direct=net.isIP(url.hostname)?[{address:url.hostname}]:await dns.lookup(url.hostname,{all:true,verbatim:true});if(!direct.length||direct.some(a=>a.address.includes(':')?blocked6(a.address):blocked4(a.address)))throw new Error('Private or reserved addresses cannot be captured');return url}
export async function safeFetch(value:string,init:RequestInit={},redirects=0):Promise<Response>{if(redirects>5)throw new Error('Too many redirects');const url=await assertPublicUrl(value);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);try{const response=await fetch(url,{...init,redirect:'manual',signal:controller.signal,headers:{'user-agent':'Keepsake/1.0 bookmark archiver',accept:'text/html,application/pdf;q=0.9,image/*;q=0.5,*/*;q=0.1',...(init.headers??{})}});if(response.status>=300&&response.status<400){const location=response.headers.get('location');if(!location)throw new Error('Redirect had no destination');return safeFetch(new URL(location,url).toString(),init,redirects+1)}return response}finally{clearTimeout(timer)}}

