import type { FastifyInstance } from 'fastify';
import { SearchSyntaxError } from '../../../../packages/search/src/parser.js';
export function installErrors(app:FastifyInstance){app.setErrorHandler((error,request,reply)=>{request.log.warn({err:error},'request failed');let status=(error as any).statusCode??400;if((error as any).code==='SQLITE_CONSTRAINT_UNIQUE')status=409;if(error.message.includes('not found'))status=404;if(error.message.includes('changed')||error.message.includes('already saved'))status=409;reply.status(status).send({type:'about:blank',title:status===404?'Not found':status===409?'Conflict':'Request could not be completed',status,detail:error.message,...(error instanceof SearchSyntaxError?{offset:error.offset}: {})})})}

