const host=(url:string)=>{try{return new URL(url).hostname.replace(/^www\./,'')}catch{return url}};
const relative=(value:string)=>{const then=new Date(value).getTime(),delta=Math.max(0,Date.now()-then),days=Math.floor(delta/86400000);return days===0?'today':days===1?'yesterday':days<30?`${days} days ago`:new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:new Date(value).getFullYear()!==new Date().getFullYear()?'numeric':undefined})};

function SaveBookmark({onClose,onSaved}:{onClose:()=>void;onSaved:(b:Bookmark)=>void}){const [form,setForm]=useState<any>({url:'',title:'',description:'',tags:'',noteMarkdown:'',faviconUrl:null,previewImageUrl:null});const [status,setStatus]=useState('');const [error,setError]=useState('');const timer=useRef<number|null>(null);const updateUrl=(url:string)=>{setForm((f:any)=>({...f,url}));setError('');setStatus('');if(timer.current)clearTimeout(timer.current);if(/^https?:\/\//i.test(url))timer.current=window.setTimeout(async()=>{setStatus('Fetching page details…');try{const m=await api.metadata(url);setForm((f:any)=>({...f,...m,url}));setStatus('Details found — everything remains editable.')}catch(e){setError((e as Error).message);setStatus('')}},650)};const submit=async(e:FormEvent)=>{e.preventDefault();setError('');setStatus('Saving…');try{const b=await api.create({...form,tags:form.tags.split(',').map((x:string)=>x.trim()).filter(Boolean)});onSaved(b)}catch(e){setError((e as Error).message);setStatus('')}};return <Modal title="Save a bookmark" onClose={onClose}><form onSubmit={submit} className="form-stack"><label>Web address<input autoFocus required type="url" value={form.url} onChange={e=>updateUrl(e.target.value)} placeholder="https://example.com/article"/></label>{status&&<div className="fetch-status"><span className={status.startsWith('Fetching')?'spinner':''}/>{status}</div>}{error&&<div className="alert error">{error}</div>}<div className="metadata-preview">{form.previewImageUrl?<img src={form.previewImageUrl} alt=""/>:<div className="preview-placeholder"><Icon name="bookmark"/></div>}<div>{form.faviconUrl&&<img className="favicon" src={form.faviconUrl} alt=""/>}<strong>{form.title||'Page title will appear here'}</strong><small>{form.description||'The page description and preview will be filled in automatically.'}</small></div></div><label>Title<input required maxLength={500} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label>