function BookmarkEditor({bookmark,onClose,onChanged,onDelete}:{bookmark:Bookmark;onClose:()=>void;onChanged:(b?:Bookmark)=>void;onDelete:()=>void}){const [form,setForm]=useState<any>({...bookmark,tags:bookmark.tags.map(t=>t.name).join(', ')});const [error,setError]=useState('');const [reader,setReader]=useState(false);const save=async(e:FormEvent)=>{e.preventDefault();try{const b=await api.update(bookmark.id,{...form,tags:form.tags.split(',').map((x:string)=>x.trim()).filter(Boolean),version:bookmark.version});onChanged(b)}catch(e){setError((e as Error).message)}};const copyAction=async()=>{if(bookmark.copyStatus==='available'){setReader(true);return}try{await api.action(bookmark.id,'capture');onChanged()}catch(e){setError((e as Error).message)}};if(reader)return <Modal title={`Saved copy — ${bookmark.title}`} onClose={()=>setReader(false)} wide><div className="reader-toolbar"><span>{bookmark.savedCopy?.kind==='pdf'?'Original PDF':'Readable page copy'} · captured {bookmark.savedCopy&&relative(bookmark.savedCopy.capturedAt)}</span><a className="secondary button" href={`/api/bookmarks/${bookmark.id}/copy/download`}>Download</a></div><iframe className="saved-reader" sandbox="" src={`/saved/${bookmark.id}`} title={`Saved copy of ${bookmark.title}`}/></Modal>;return <Modal title="Bookmark details" onClose={onClose} wide><form onSubmit={save} className="form-stack"><div className="detail-heading"><div className="site-icon">{bookmark.faviconUrl?<img src={bookmark.faviconUrl} alt=""/>:bookmark.title[0]?.toUpperCase()}</div><div><a href={bookmark.url} target="_blank" rel="noreferrer">{host(bookmark.url)} <Icon name="external"/></a><span>Saved {relative(bookmark.createdAt)}</span></div></div>{error&&<div className="alert error">{error}</div>}<div className="field-grid"><label>Title<input required value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Web address<input required type="url" value={form.url} onChange={e=>setForm({...form,url:e.target.value})}/></label></div><label>Description<textarea rows={3} value={form.description??''} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>Tags <span className="hint">comma separated</span><input value={form.tags} onChange={e=>setForm({...form,tags:e.target.value})}/></label><label>Note</label><RichNoteEditor value={form.noteMarkdown} onChange={v=>setForm({...form,noteMarkdown:v})} previewHtml={previewMarkdown(form.noteMarkdown)}/><div className={`copy-panel ${bookmark.copyStatus}`}><div><strong>{bookmark.copyStatus==='available'?'Saved copy ready':bookmark.copyStatus==='pending'?'Saving a readable copy…':'Could not save a copy'}</strong><span>{bookmark.copyStatus==='available'&&bookmark.savedCopy?`${bookmark.savedCopy.kind.toUpperCase()} · ${(bookmark.savedCopy.size/1024).toFixed(0)} KB · ${new Date(bookmark.savedCopy.capturedAt).toLocaleString()}`:bookmark.copyErrorCode||'You can keep organizing this bookmark while capture runs.'}</span></div><button type="button" className="secondary" onClick={copyAction}>{bookmark.copyStatus==='available'?'Read saved copy':'Retry'}</button>{bookmark.copyStatus==='available'&&<button type="button" className="text-button" onClick={async()=>{if(confirm('Capture a fresh copy? The current copy stays available until the new one succeeds.')){await api.action(bookmark.id,'capture');onChanged()}}}>Refresh copy</button>}</div>{bookmark.noteHtml&&<details><summary>Current rendered note</summary><RichNoteView html={bookmark.noteHtml}/></details>}<footer className="modal-actions split"><button type="button" className="danger-text" onClick={onDelete}>Delete permanently</button><span/><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary">Save changes</button></footer></form></Modal>}

function BookmarkCard({bookmark,selected,onSelect,onOpen,onAction}:{bookmark:Bookmark;selected:boolean;onSelect:()=>void;onOpen:()=>void;onAction:(action:string)=>void}){return <article className={`bookmark-card ${selected?'selected':''}`}><label className="select-box"><input type="checkbox" checked={selected} onChange={onSelect}/><span/></label>{bookmark.previewImageUrl?<img className="card-image" src={bookmark.previewImageUrl} alt="" loading="lazy"/>:<div className="card-image placeholder"><span>{host(bookmark.url).slice(0,2).toUpperCase()}</span></div>}<div className="card-body"><div className="card-top"><div className="site-line">{bookmark.faviconUrl&&<img src={bookmark.faviconUrl} alt=""/>}<span>{host(bookmark.url)}</span></div><button className="icon-button" aria-label={`Edit ${bookmark.title}`} onClick={onOpen}><Icon name="more"/></button></div><button className="card-title" onClick={onOpen}>{bookmark.title}</button>{bookmark.description&&<p>{bookmark.description}</p>}<div className="tag-row">{bookmark.tags.map(t=><span key={t.id}>#{t.name}</span>)}</div><div className="card-meta"><span className={`status-dot ${bookmark.copyStatus}`} title={`Saved copy: ${bookmark.copyStatus}`}/><span>{bookmark.copyStatus==='available'?'copy saved':bookmark.copyStatus==='pending'?'saving copy':'copy failed'}</span><span>·</span><span>{relative(bookmark.createdAt)}</span></div></div><div className="card-actions"><button className="quiet" onClick={()=>onAction(bookmark.readStatus==='read'?'unread':'read')}><Icon name="check"/>{bookmark.readStatus==='read'?'Mark unread':'Mark read'}</button><a className="quiet" href={bookmark.url} target="_blank" rel="noreferrer"><Icon name="external"/>Open</a></div></article>}

function Portability({onImported}:{onImported:()=>void}){const [file,setFile]=useState<File|null>(null),[result,setResult]=useState<any>(null),[busy,setBusy]=useState(false),[scope,setScope]=useState('all'),[ack,setAck]=useState(false),[error,setError]=useState('');return <div className="settings-page"><div className="page-heading"><div><span className="eyebrow">Bring your collection with you</span><h1>Import & export</h1><p>Move bookmarks from common browsers or take a portable copy with you.</p></div></div><section className="settings-card"><div className="section-icon"><Icon name="download"/></div><div><h2>Import browser bookmarks</h2><p>Choose a Netscape bookmark HTML file exported by Chrome, Firefox, Safari, or another browser. Folder names become tags, and every new bookmark starts unread with a saved-copy job.</p><input type="file" accept=".html,.htm,text/html" onChange={e=>setFile(e.target.files?.[0]??null)}/>{error&&<div className="alert error">{error}</div>}{result&&<div className="import-result"><strong>Import complete</strong><span>{result.created} added · {result.duplicates} duplicates · {result.skipped} skipped</span>{result.issues?.slice(0,4).map((i:any,n:number)=><small key={n}>{i.message}</small>)}</div>}<button className="primary" disabled={!file||busy} onClick={async()=>{if(!file)return;setBusy(true);setError('');try{setResult(await api.import(file));onImported()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}>{busy?'Importing…':'Import bookmarks'}</button></div></section><section className="settings-card"><div className="section-icon"><Icon name="external"/></div><div><h2>Export bookmarks</h2><p>Browser bookmark files contain links and titles only. Tags, notes, read and archive state, images, saved copies, saved searches, and preferences will not be included.</p><label>Collection<select value={scope} onChange={e=>setScope(e.target.value)}><option value="all">All bookmarks</option><option value="active">Active bookmarks</option><option value="archived">Archived bookmarks</option></select></label><label className="check-line"><input type="checkbox" checked={ack} onChange={e=>setAck(e.target.checked)}/> I understand which information the browser format cannot carry.</label><a className={`button primary ${!ack?'disabled':''}`} aria-disabled={!ack} href={ack?`/api/exports?scope=${scope}`:undefined}>Export HTML file</a></div></section></div>}

function Preferences({value,onSave}:{value:any;onSave:(v:any)=>void}){const [form,setForm]=useState(value);return <div className="settings-page"><div className="page-heading"><div><span className="eyebrow">Make it yours</span><h1>Display preferences</h1><p>Choose how your collection looks when you return.</p></div></div><section className="settings-card"><div className="section-icon"><Icon name="settings"/></div><form onSubmit={async e=>{e.preventDefault();const saved=await api.savePreferences(form);localStorage.setItem('textSize',saved.textSize);document.documentElement.dataset.textSize=saved.textSize;onSave(saved)}}><h2>Collection display</h2><div className="field-grid"><label>Default sort<select value={form.defaultSort} onChange={e=>setForm({...form,defaultSort:e.target.value})}><option value="created_at">Date saved</option><option value="updated_at">Last updated</option><option value="title">Title</option></select></label><label>Direction<select value={form.sortDirection} onChange={e=>setForm({...form,sortDirection:e.target.value})}><option value="desc">Descending</option><option value="asc">Ascending</option></select></label></div><fieldset><legend>Text size</legend><div className="size-options">{['small','medium','large'].map(size=><label key={size} className={form.textSize===size?'chosen':''}><input type="radio" name="size" value={size} checked={form.textSize===size} onChange={()=>setForm({...form,textSize:size})}/><span className={`sample ${size}`}>Aa</span><strong>{size[0].toUpperCase()+size.slice(1)}</strong></label>)}</div></fieldset><button className="primary">Save preferences</button></form></section></div>}

export default function App(){const [section,setSection]=useState<Section>('library'),[bookmarks,setBookmarks]=useState<Bookmark[]>([]),[total,setTotal]=useState(0),[tags,setTags]=useState<Tag[]>([]),[views,setViews]=useState<any[]>([]),[query,setQuery]=useState(''),[selectedTags,setSelectedTags]=useState<string[]>([]),[sort,setSort]=useState('created_at'),[direction,setDirection]=useState('desc'),[selected,setSelected]=useState(new Set<string>()),[saveOpen,setSaveOpen]=useState(false),[editing,setEditing]=useState<Bookmark|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true),[notice,setNotice]=useState(''),[prefs,setPrefs]=useState<any>({defaultSort:'created_at',sortDirection:'desc',textSize:'medium'}),[counts,setCounts]=useState({active:0,unread:0,archived:0}),[saveViewOpen,setSaveViewOpen]=useState(false),[viewName,setViewName]=useState('');const scope=section==='unread'?'unread':section==='archived'?'archived':'active';
 const refreshMeta=useCallback(async()=>{const [tagData,viewData,a,u,r]=await Promise.all([api.tags(),api.views(),api.list({scope:'active',pageSize:'1'}),api.list({scope:'unread',pageSize:'1'}),api.list({scope:'archived',pageSize:'1'})]);setTags(tagData.items);setViews(viewData.items);setCounts({active:a.total,unread:u.total,archived:r.total})},[]);
 const load=useCallback(async(silent=false)=>{if(!['library','unread','archived'].includes(section))return;if(!silent)setLoading(true);setError('');try{const data=await api.list({scope,q:query,tags:selectedTags.join(','),sort,direction,pageSize:'60'});setBookmarks(data.items);setTotal(data.total);await refreshMeta()}catch(e){setError((e as Error).message)}finally{setLoading(false)}},[section,scope,query,selectedTags,sort,direction,refreshMeta]);
 useEffect(()=>{api.preferences().then(p=>{setPrefs(p);setSort(p.defaultSort);setDirection(p.sortDirection);document.documentElement.dataset.textSize=p.textSize;localStorage.setItem('textSize',p.textSize)}).catch(()=>{});void refreshMeta()},[refreshMeta]);useEffect(()=>{const id=setTimeout(()=>void load(),180);return()=>clearTimeout(id)},[load]);useEffect(()=>{if(bookmarks.some(b=>b.copyStatus==='pending')){const id=setInterval(()=>void load(true),2200);return()=>clearInterval(id)}},[bookmarks,load]);
 const changeSection=(next:Section)=>{setSection(next);setSelected(new Set());setQuery('');setSelectedTags([])};const action=async(b:Bookmark,action:string)=>{try{if(action==='read'||action==='unread')await api.action(b.id,'read',{read:action==='read'});else await api.action(b.id,action);await load(true)}catch(e){setError((e as Error).message)}};const remove=async(b:Bookmark)=>{const copies=b.savedCopy?1:0;if(!confirm(`Permanently delete “${b.title}”?${copies?' Its saved copy will also be removed.':''} This cannot be undone.`))return;await api.remove(b.id,copies);setEditing(null);setNotice('Bookmark permanently deleted.');await load(true)};const bulk=async(action:string,data:any={})=>{if(action==='delete'&&!confirm(`Permanently delete ${selected.size} bookmarks and their saved copies? This cannot be undone.`))return;try{const result=await api.bulk([...selected],action,data);setNotice(result.failed?`${result.succeeded} changed; ${result.failed} could not be changed.`:`${result.succeeded} bookmarks updated.`);setSelected(new Set());await load(true)}catch(e){setError((e as Error).message)}};
 const title=section==='unread'?'Read later':section==='archived'?'Archive':'Your library';const subtitle=section==='unread'?'Everything you still want to read, in one calm queue.':section==='archived'?'Bookmarks put away for safekeeping.':'A considered home for everything worth keeping.';const visibleCollection=['library','unread','archived'].includes(section);
 return <div className="app-shell" data-harness-ready="true"><aside className="sidebar"><a className="brand" href="#" onClick={()=>changeSection('library')}><span className="brand-mark"><Icon name="bookmark"/></span><span>Keepsake<small>YOUR PRIVATE LIBRARY</small></span></a><nav aria-label="Main navigation"><button className={section==='library'?'active':''} onClick={()=>changeSection('library')}><Icon name="library"/><span>Library</span><b>{counts.active}</b></button><button className={section==='unread'?'active':''} onClick={()=>changeSection('unread')}><Icon name="unread"/><span>Read later</span><b>{counts.unread}</b></button><button className={section==='archived'?'active':''} onClick={()=>changeSection('archived')}><Icon name="archive"/><span>Archive</span><b>{counts.archived}</b></button></nav><div className="sidebar-section"><div><span>SAVED VIEWS</span><button aria-label="Save current view" onClick={()=>setSaveViewOpen(true)}>+</button></div>{views.length?views.map(v=><button key={v.id} className="saved-link" onClick={()=>{setSection('library');setQuery(v.query);setSelectedTags((v.tagIds??[]).map((id:string)=>tags.find(t=>t.id===id)?.name).filter(Boolean) as string[])}}><Icon name="search"/><span>{v.name}</span></button>):<p>Save a search to find it here.</p>}</div><div className="sidebar-bottom"><button className={section==='portability'?'active':''} onClick={()=>changeSection('portability')}><Icon name="download"/>Import & export</button><button className={section==='settings'?'active':''} onClick={()=>changeSection('settings')}><Icon name="settings"/>Preferences</button><div className="privacy"><span>◆</span><div><strong>Private by design</strong><small>Your library stays on this device.</small></div></div></div></aside><main><header className="topbar"><div className="global-search"><Icon name="search"/><input aria-label="Search bookmarks" value={query} onChange={e=>setQuery(e.target.value)} disabled={!visibleCollection} placeholder='Search words, "exact phrases", #tags…'/>{query&&<button onClick={()=>setQuery('')} aria-label="Clear search">×</button>}<kbd>⌘ K</kbd></div><button className="primary save-button" onClick={()=>setSaveOpen(true)}><Icon name="plus"/>Save bookmark</button></header>{notice&&<div className="toast" role="status">{notice}<button onClick={()=>setNotice('')}>×</button></div>}{visibleCollection?<><div className="page-heading"><div><span className="eyebrow">{section==='library'?'Collected with intention':section==='unread'?'Your reading queue':'Safe, but out of the way'}</span><h1>{title}</h1><p>{subtitle}</p></div><div className="heading-stat"><strong>{total}</strong><span>{total===1?'bookmark':'bookmarks'}</span></div></div><div className="controls"><div className="filter-tags"><button className={!selectedTags.length?'active':''} onClick={()=>setSelectedTags([])}>All</button>{tags.slice(0,8).map(t=><button key={t.id} className={selectedTags.includes(t.name)?'active':''} onClick={()=>setSelectedTags(s=>s.includes(t.name)?s.filter(x=>x!==t.name):[...s,t.name])}>#{t.name}</button>)}</div><div className="sort-control"><span>Sort</span><select value={`${sort}:${direction}`} onChange={e=>{const [s,d]=e.target.value.split(':');setSort(s!);setDirection(d!)}}><option value="created_at:desc">Newest saved</option><option value="created_at:asc">Oldest saved</option><option value="updated_at:desc">Recently updated</option><option value="title:asc">Title A–Z</option><option value="title:desc">Title Z–A</option></select></div></div>{error&&<div className="alert error search-error"><strong>Search needs a small fix.</strong> {error}<button onClick={()=>setError('')}>Dismiss</button></div>}{bookmarks.length>0&&<div className="selection-row"><label><input type="checkbox" checked={bookmarks.every(b=>selected.has(b.id))} onChange={e=>setSelected(e.target.checked?new Set(bookmarks.map(b=>b.id)):new Set())}/> Select all visible</label><span>{total} result{total===1?'':'s'}</span></div>}{loading?<div className="loading-grid">{[1,2,3,4].map(x=><div key={x}/>)}</div>:bookmarks.length?<div className="bookmark-grid">{bookmarks.map(b=><BookmarkCard key={b.id} bookmark={b} selected={selected.has(b.id)} onSelect={()=>setSelected(s=>{const n=new Set(s);n.has(b.id)?n.delete(b.id):n.add(b.id);return n})} onOpen={()=>setEditing(b)} onAction={a=>void action(b,a)}/>)}</div>:<div className="empty-state"><div><Icon name={section==='archived'?'archive':section==='unread'?'unread':'bookmark'}/></div><h2>{query||selectedTags.length?'No bookmarks match that search':section==='unread'?'Your reading queue is clear':section==='archived'?'Nothing is archived':'Your library is ready'}</h2><p>{query?'Try fewer words, remove a filter, or check your search operators.':section==='library'?'Save your first link and Keepsake will fill in its details and make a readable copy.':section==='unread'?'New bookmarks begin here until you mark them read.':'Archived bookmarks will stay here with their notes and saved copies.'}</p>{section==='library'&&!query&&<button className="primary" onClick={()=>setSaveOpen(true)}><Icon name="plus"/>Save your first bookmark</button>}</div>}</>:section==='saved'?<div/>:section==='portability'?<Portability onImported={()=>{void refreshMeta();setNotice('Import complete. Saved copies are being prepared.')}}/>:<Preferences value={prefs} onSave={p=>{setPrefs(p);setSort(p.defaultSort);setDirection(p.sortDirection);setNotice('Preferences saved.')}}/>}</main>{selected.size>0&&<div className="bulk-bar"><strong>{selected.size} selected</strong><button onClick={()=>void bulk('read')}>Mark read</button><button onClick={()=>void bulk('unread')}>Mark unread</button><button onClick={()=>{const value=prompt('Tags to add, separated by commas');if(value)void bulk('addTags',{tags:value.split(',')})}}>Add tags</button>{section==='archived'?<button onClick={()=>void bulk('restore')}>Restore</button>:<button onClick={()=>void bulk('archive')}>Archive</button>}<button className="danger-text" onClick={()=>void bulk('delete')}>Delete</button><button className="icon-button" onClick={()=>setSelected(new Set())} aria-label="Clear selection">×</button></div>}{saveOpen&&<SaveBookmark onClose={()=>setSaveOpen(false)} onSaved={()=>{setSaveOpen(false);setNotice('Bookmark saved. A readable copy is being prepared.');void load(true)}}/>}{editing&&<BookmarkEditor bookmark={editing} onClose={()=>setEditing(null)} onChanged={b=>{if(b)setEditing(b);void load(true)}} onDelete={()=>void remove(editing)}/>} {saveViewOpen&&<Modal title="Save this view" onClose={()=>setSaveViewOpen(false)}><form className="form-stack" onSubmit={async e=>{e.preventDefault();await api.saveView({name:viewName,query,tagIds:tags.filter(t=>selectedTags.includes(t.name)).map(t=>t.id)});setSaveViewOpen(false);setViewName('');await refreshMeta();setNotice('Saved view added to the sidebar.')}}><p>Keep this search and its tag filters for quick access. Results always reflect your current library.</p><label>Name<input autoFocus required maxLength={100} value={viewName} onChange={e=>setViewName(e.target.value)} placeholder="Weekend reading"/></label><div className="saved-criteria"><strong>Search</strong><span>{query||'Any words'}</span><strong>Tags</strong><span>{selectedTags.length?selectedTags.map(t=>`#${t}`).join(' + '):'Any tags'}</span></div><footer className="modal-actions"><button type="button" className="secondary" onClick={()=>setSaveViewOpen(false)}>Cancel</button><button className="primary">Save view</button></footer></form></Modal>}</div>}

