     1	import { useCallback,useEffect,useMemo,useRef,useState,type FormEvent } from 'react';
     2	import { api,type Bookmark,type Tag } from './api';
     3	import { Icon } from './components/Icons';
     4	import { Modal } from './components/Modal';
     5	import { RichNoteEditor } from './features/notes/RichNoteEditor';
     6	import { RichNoteView } from './features/notes/RichNoteView';
     7	
     8	type Section='library'|'unread'|'archived'|'saved'|'portability'|'settings';
     9	const previewMarkdown=(v:string)=>{const escape=(s:string)=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');return escape(v).replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>').replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\n/g,'<br>')};
    10	const host=(url:string)=>{try{return new URL(url).hostname.replace(/^www\./,'')}catch{return url}};
    11	const relative=(value:string)=>{const then=new Date(value).getTime(),delta=Math.max(0,Date.now()-then),days=Math.floor(delta/86400000);return days===0?'today':days===1?'yesterday':days<30?`${days} days ago`:new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:new Date(value).getFullYear()!==new Date().getFullYear()?'numeric':undefined})};
    12	
    13	function SaveBookmark({onClose,onSaved}:{onClose:()=>void;onSaved:(b:Bookmark)=>void}){const [form,setForm]=useState<any>({url:'',title:'',description:'',tags:'',noteMarkdown:'',faviconUrl:null,previewImageUrl:null});const [status,setStatus]=useState('');const [error,setError]=useState('');const timer=useRef<number|null>(null);const updateUrl=(url:string)=>{setForm((f:any)=>({...f,url}));setError('');setStatus('');if(timer.current)clearTimeout(timer.current);if(/^https?:\/\//i.test(url))timer.current=window.setTimeout(async()=>{setStatus('Fetching page details…');try{const m=await api.metadata(url);setForm((f:any)=>({...f,...m,url}));setStatus('Details found — everything remains editable.')}catch(e){setError((e as Error).message);setStatus('')}},650)};const submit=async(e:FormEvent)=>{e.preventDefault();setError('');setStatus('Saving…');try{const b=await api.create({...form,tags:form.tags.split(',').map((x:string)=>x.trim()).filter(Boolean)});onSaved(b)}catch(e){setError((e as Error).message);setStatus('')}};return <Modal title="Save a bookmark" onClose={onClose}><form onSubmit={submit} className="form-stack"><label>Web address<input autoFocus required type="url" value={form.url} onChange={e=>updateUrl(e.target.value)} placeholder="https://example.com/article"/></label>{status&&<div className="fetch-status"><span className={status.startsWith('Fetching')?'spinner':''}/>{status}</div>}{error&&<div className="alert error">{error}</div>}<div className="metadata-preview">{form.previewImageUrl?<img src={form.previewImageUrl} alt=""/>:<div className="preview-placeholder"><Icon name="bookmark"/></div>}<div>{form.faviconUrl&&<img className="favicon" src={form.faviconUrl} alt=""/>}<strong>{form.title||'Page title will appear here'}</strong><small>{form.description||'The page description and preview will be filled in automatically.'}</small></div></div><label>Title<input required maxLength={500} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Description<textarea rows={3} maxLength={4000} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>Tags <span className="hint">comma separated</span><input value={form.tags} onChange={e=>setForm({...form,tags:e.target.value})} placeholder="research, design"/></label><footer className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={!form.url||!form.title}>Save bookmark</button></footer></form></Modal>}
    14	
    15	function BookmarkEditor({bookmark,onClose,onChanged,onDelete}:{bookmark:Bookmark;onClose:()=>void;onChanged:(b?:Bookmark)=>void;onDelete:()=>void}){const [form,setForm]=useState<any>({...bookmark,tags:bookmark.tags.map(t=>t.name).join(', ')});const [error,setError]=useState('');const [reader,setReader]=useState(false);const save=async(e:FormEvent)=>{e.preventDefault();try{const b=await api.update(bookmark.id,{...form,tags:form.tags.split(',').map((x:string)=>x.trim()).filter(Boolean),version:bookmark.version});onChanged(b)}catch(e){setError((e as Error).message)}};const copyAction=async()=>{if(bookmark.copyStatus==='available'){setReader(true);return}try{await api.action(bookmark.id,'capture');onChanged()}catch(e){setError((e as Error).message)}};if(reader)return <Modal title={`Saved copy — ${bookmark.title}`} onClose={()=>setReader(false)} wide><div className="reader-toolbar"><span>{bookmark.savedCopy?.kind==='pdf'?'Original PDF':'Readable page copy'} · captured {bookmark.savedCopy&&relative(bookmark.savedCopy.capturedAt)}</span><a className="secondary button" href={`/api/bookmarks/${bookmark.id}/copy/download`}>Download</a></div><iframe className="saved-reader" sandbox="" src={`/saved/${bookmark.id}`} title={`Saved copy of ${bookmark.title}`}/></Modal>;return <Modal title="Bookmark details" onClose={onClose} wide><form onSubmit={save} className="form-stack"><div className="detail-heading"><div className="site-icon">{bookmark.faviconUrl?<img src={bookmark.faviconUrl} alt=""/>:bookmark.title[0]?.toUpperCase()}</div><div><a href={bookmark.url} target="_blank" rel="noreferrer">{host(bookmark.url)} <Icon name="external"/></a><span>Saved {relative(bookmark.createdAt)}</span></div></div>{error&&<div className="alert error">{error}</div>}<div className="field-grid"><label>Title<input required value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Web address<input required type="url" value={form.url} onChange={e=>setForm({...form,u