import Database from 'better-sqlite3';import fs from 'node:fs/promises';import path from 'node:path';
const command=process.argv[2],target=path.resolve(process.argv[3]??path.join(process.cwd(),'backups',new Date().toISOString().replace(/[:.]/g,'-'))),data=path.resolve(process.env.DATA_DIR??path.join(process.cwd(),'data')),dbPath=path.join(data,'app.sqlite');
if(command==='backup'){await fs.mkdir(path.join(target,'blobs'),{recursive:true});const db=new Database(dbPath,{readonly:true});await db.backup(path.join(target,'app.sqlite'));const rows=db.prepare('SELECT digest,path,size_bytes,media_type FROM blobs').all();db.close();for(const row of rows){const destination=path.join(target,'blobs',row.digest.slice(0,2),row.digest);await fs.mkdir(path.dirname(destination),{recursive:true});await fs.copyFile(row.path,destination)}await fs.writeFile(path.join(target,'manifest.json'),JSON.stringify({createdAt:new Date().toISOString(),blobs:rows.map(({digest,size_bytes,media_type})=>({digest,sizeBytes:size_bytes,mediaType:media_type}))},null,2));console.log(`Backup written to ${target}`)}else if(command==='restore'){if(!process.argv[3])throw new Error('Usage: node scripts/backup.mjs restore <backup-directory>');await fs.access(path.join(target,'app.sqlite'));await fs.mkdir(data,{recursive:true});await fs.copyFile(path.join(target,'app.sqlite'),dbPath);await fs.cp(path.join(target,'blobs'),path.join(data,'blobs'),{recursive:true,force:true});console.log(`Backup restored from ${target}`)}else throw new Error('Use backup or restore');

/work/scripts/start.mjs.content:
import { spawn } from 'node:child_process';
import fs from 'node:fs';
const entry=new URL('../dist/server/apps/server/src/main.js',import.meta.url);
if(!fs.existsSync(entry))throw new Error('The prepared application is missing. Run npm run build first.');
const child=spawn(process.execPath,[entry.pathname],{stdio:'inherit',env:process.env});
for(const signal of ['SIGINT','SIGTERM'])process.on(signal,()=>child.kill(signal));
child.on('exit',(code,signal)=>process.exitCode=signal?1:(code??1));

