const patch = "*** Begin Patch
*** Add File: /work/tests/performance/collection.perf.test.ts
+import { afterAll,beforeAll,describe,expect,it } from 'vitest';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import { openDatabase,type DB } from '../../packages/persistence/src/database.js';import { migrate } from '../../packages/persistence/src/migrate.js';import { Store } from '../../packages/persistence/src/store.js';
+let dir:string,db:DB,store:Store,ids:string[]=[];beforeAll(()=>{dir=fs.mkdtempSync(path.join(os.tmpdir(),'keepsake-perf-'));db=openDatabase(path.join(dir,'db.sqlite'));migrate(db);const insert=db.prepare("INSERT INTO bookmarks(id,url,normalized_url,title,description,note_text,read_status,copy_status,created_at,updated_at) VALUES(?,?,?,?,?,'','unread','failed',?,?)"),fts=db.prepare("INSERT INTO bookmark_fts(bookmark_id,title,url,description,note_text,tags) VALUES(?,?,?,?,?,'')"),stamp=new Date().toISOString();db.transaction(()=>{for(let i=0;i<10000;i++){const id=`00000000-0000-4000-8000-${String(i).padStart(12,'0')}`,url=`https://example.com/${i}`,title=i===6789?'Needle field guide':`Reference ${i}`;insert.run(id,url,url,title,`Description ${i}`,stamp,stamp);fts.run(id,title,url,`Description ${i}`,'');ids.push(id)}})()});afterAll(()=>{db.close();fs.rmSync(dir,{recursive:true,force:true})});describe('approved scale targets',()=>{it('finds a known item among 10,000 within one second',()=>{const start=performance.now(),result=store.list({q:'needle',pageSize:30});expect(result.total).toBe(1);expect(performance.now()-start).toBeLessThan(1000)});it('bulk-updates 500 bookmarks within five seconds',()=>{const start=performance.now(),result=store.bulk(ids.slice(0,500),'read');expect(result.succeeded).toBe(500);expect(performance.now()-start).toBeLessThan(5000)})});
*** Add File: /work/tests/e2e/accessibility.spec.ts
+import { test,expect } from '@playwright/test';
+test('primary routes are keyboard reachable and remain usable at large text',async({page})=>{await page.goto('/');await expect(page.locator('[data-harness-ready=true]')).toBeVisible();await page.keyboard.press('Tab');await expect(page.locator(':focus')).toBeVisible();await page.getByRole('button',{name:'Preferences'}).click();await page.getByLabel('Large').check();await page.getByRole('button',{name:'Save preferences'}).click();await expect(page.locator('html')).toHaveAttribute('data-text-size','large');const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-document.documentElement.clientWidth);expect(overflow).toBeLessThanOrEqual(1);await page.getByRole('button',{name:'Import & export'}).click();await expect(page.getByRole('heading',{name:'Import & export'})).toBeVisible()});
*** Add File: /work/tests/e2e/saved-copy.spec.ts
+import { test,expect } from '@playwright/test';
+test('captured HTML remains available through the sandboxed reader',async({request,page})=>{const stamp=Date.now(),created=await request.post('/api/bookmarks',{data:{url:`https://example.com/?copy-${stamp}`,title:`Offline ${stamp}`}}),bookmark=await created.json();let current:any;await expect.poll(async()=>{current=await (await request.get(`/api/bookmarks/${bookmark.id}`)).json();return current.copyStatus},{timeout:30000}).toBe('available');await page.goto('/');await page.getByRole('button',{name:`Offline ${stamp}`,exact:true}).click();await page.getByRole('button',{name:'Read saved copy'}).click();const frame=page.locator('iframe[title^="Saved copy"]');await expect(frame).toHaveAttribute('sandbox','');await expect(frame.contentFrame().getByRole('heading',{name:'Example Domain'})).toBeVisible();const html=await (await request.get(`/saved/${bookmark.id}`)).text();expect(html).not.toMatch(/<script|onload=/i);await request.delete(`/api/bookmarks/${bookmark.id}?expectedCopies=1`)});
*** Add File: /work/packages/test-fixtures/capture-corpus/simple-article.html
+<!doctype html><html><head><title>Fixture article</title><meta name="description" content="A deterministic readable article."></head><body><main><h1>Fixture article</h1><p>The primary text must remain readable in a retained copy.</p><img src="hero.png" alt="Essential illustration"><script>window.fixtureActive=true</script></main></body></html>
*** Add File: /work/docs/performance-baseline.md
+# Performance baseline
+
+Measured on the provided development container with Node.js 24 and SQLite WAL. Automated thresholds enforce discovery among 10,000 bookmarks in under 1 second and a 500-item bulk read-state mutation in under 5 seconds. Import/export remain streaming at the HTTP boundary and collection pagination is capped at 100 records per response.
*** End Patch";
text(await tools.apply_patch(patch));

