import { test,expect } from '@playwright/test';
test('rich notes are searchable and saved views re-evaluate current data',async({page,request})=>{const stamp=Date.now(),created=await request.post('/api/bookmarks',{data:{url:`https://example.com/notes-${stamp}`,title:`Notes ${stamp}`,noteMarkdown:'# Reading notes\n\nA **singularphrase** to remember.',tags:['Essays']}}),bookmark=await created.json(),tag=bookmark.tags[0];const view=await (await request.post('/api/saved-views',{data:{name:`Essay view ${stamp}`,query:'singularphrase',tagIds:[tag.id]}})).json();await page.goto('/');await page.getByRole('button',{name:`Essay view ${stamp}`}).click();await expect(page.getByRole('button',{name:`Notes ${stamp}`,exact:true})).toBeVisible();await page.getByRole('button',{name:`Notes ${stamp}`,exact:true}).click();await expect(page.getByText('Reading notes')).toBeVisible();await request.delete(`/api/saved-views/${view.id}`);await request.delete(`/api/bookmarks/${bookmark.id}?expectedCopies=${bookmark.savedCopy?1:0}`)});

