rks SET current_saved_copy_id=?,copy_status='available',copy_error_code=NULL WHERE id=?").run(copyId,bookmarkId);db.prepare("UPDATE capture_attempts SET state='available',updated_at=? WHERE id=?").run(stamp,attemptId)}})()}catch(error){const detail=(error as Error).message.slice(0,500);db.transaction(()=>{db.prepare("UPDATE capture_attempts SET state='failed',error_code='capture_failed',error_detail=?,updated_at=? WHERE id=?").run(detail,now(),attemptId);db.prepare("UPDATE bookmarks SET copy_status=CASE WHEN current_saved_copy_id IS NULL THEN 'failed' ELSE copy_status END,copy_error_code=? WHERE id=?").run(detail,bookmarkId)})()}}
